'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {openingCents,validateOpeningAction,readOpeningActionReceipt,type OpeningAction} from '@/lib/financial-opening-action';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
type Row={id:string;category:string;reference:string;remaining:string};
export function FinancialOpeningAction({scope,reservation,rows,onLocked,onCompleted}:{scope:HandoffScope;reservation:string;rows:Row[];onLocked:(locked:boolean)=>void;onCompleted:()=>void}){
 const [pending,setPending]=useState<OpeningAction|null>(null),[setup,setSetup]=useState<AccountingSetup|null>(null),[kind,setKind]=useState<'application'|'external'>('application'),[source,setSource]=useState(''),[target,setTarget]=useState(''),[clearing,setClearing]=useState(''),[period,setPeriod]=useState(''),[date,setDate]=useState(''),[amount,setAmount]=useState(''),[reference,setReference]=useState(''),[reason,setReason]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const key=['irp.opening.action.v1',scope.tenant,scope.property,scope.actor,reservation].join(':'),alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw) as OpeningAction;validateOpeningAction(p,scope,reservation);setPending(p)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore transaction.')}return()=>{alive.current=false}},[key]);
 useEffect(()=>{onLocked(!ready||busy||!!pending)},[ready,busy,pending,onLocked]);
 function changed(){setConfirmed(false);setMessage('')}
 async function run(action:'setup'|'save'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{const identify=async()=>{const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the account.')};await identify();const base={p_tenant:scope.tenant,p_property:scope.property};
   if(action==='setup'){if(pending)throw Error('Resolve the saved transaction first.');const value=readAccountingSetup(await hotelRpc('gl_setup',base),scope.tenant,scope.property);await identify();if(alive.current)setSetup(value);return}
   let p=pending;if(!p){if(action!=='save'||!confirmed)throw Error('Review and confirm the transaction.');const selected=rows.find(r=>r.id===source);if(!selected)throw Error('Choose a source balance.');p={id:crypto.randomUUID(),scope,reservation,kind,source,target,clearing,externalKind:selected.category==='receivable'?'recorded_collection':'recorded_refund',period,date,amount:openingCents(amount),reference:reference.trim(),reason:reason.trim()};validateOpeningAction(p,scope,reservation);if(sessionStorage.getItem(key))throw Error('Recover the existing transaction first.');sessionStorage.setItem(key,JSON.stringify(p));setPending(p)}
   let complete=false,cancelled=false;
   if(action==='save'){if(!confirmed)throw Error('Confirm the saved transaction.');const result=p.kind==='application'?await hotelRpc<Record<string,unknown>>('apply_financial_opening',{...base,p_request:p.id,p_source:p.source,p_target:p.target,p_amount:p.amount,p_period:p.period,p_date:p.date,p_reason:p.reason}):await hotelRpc<Record<string,unknown>>('record_financial_opening_external',{...base,p_request:p.id,p_opening:p.source,p_kind:p.externalKind,p_amount:p.amount,p_clearing:p.clearing,p_period:p.period,p_date:p.date,p_reference:p.reference,p_reason:p.reason});readOpeningActionReceipt(result,p);complete=true}
   else{if(action==='cancel'){if(!cancelConfirmed)throw Error('Confirm cancellation.');await hotelRpc('cancel_financial_opening_action',{...base,p_kind:p.kind,p_request:p.id,p_confirmed:true})}const status=await hotelRpc<Record<string,unknown>>('financial_opening_action_status',{...base,p_kind:p.kind,p_request:p.id});if(status.schema_version!==1||status.tenant_id!==scope.tenant||status.property_id!==scope.property||status.actor_id!==scope.actor||status.request_id!==p.id||status.kind!==p.kind||typeof status.found!=='boolean'||typeof status.cancelled!=='boolean'||status.found&&status.cancelled||!status.found&&status.result!==null)throw Error('Transaction status does not match this request.');if(status.found){readOpeningActionReceipt(status.result as Record<string,unknown>,p);complete=true}cancelled=status.cancelled}
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setConfirmed(false);setCancelConfirmed(false);setMessage(complete?'Migrated balance transaction recorded.':'Balance transaction request cancelled.');if(complete)onCompleted()}else setMessage('No transaction found. Retry or cancel the saved request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to record transaction.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 return <section aria-label="Migrated balance transaction"><h4>Use or settle a migrated balance</h4><p>External collections and refunds record activity completed elsewhere. They do not transfer money.</p>{pending?<p>Saved {pending.kind==='application'?'fund application':pending.externalKind.replaceAll('_',' ')}: {bankCloseMoney(pending.amount)} on {pending.date}. Source {pending.source}. {pending.reason}</p>:<><button type="button" disabled={busy||!ready} onClick={()=>void run('setup')}>Load transaction accounts</button><fieldset disabled={busy||!ready} onChange={changed}><label>Balance transaction<select value={kind} onChange={e=>{setKind(e.target.value as typeof kind);setSource('')}}><option value="application">Apply funds to a migrated receivable</option><option value="external">Record external collection or refund</option></select></label><label>Source balance<select value={source} onChange={e=>setSource(e.target.value)}><option value="">Choose source balance</option>{rows.filter(r=>kind==='external'||r.category!=='receivable').map(r=><option key={r.id} value={r.id}>{r.reference} · {r.category} · {bankCloseMoney(r.remaining)}</option>)}</select></label>{kind==='application'?<label>Receivable to settle<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Choose receivable</option>{rows.filter(r=>r.category==='receivable').map(r=><option key={r.id} value={r.id}>{r.reference} · {bankCloseMoney(r.remaining)}</option>)}</select></label>:<><label>Clearing account<select value={clearing} onChange={e=>setClearing(e.target.value)}><option value="">Choose clearing account</option>{setup?.accounts.filter(a=>a.active&&a.kind==='asset').map(a=><option key={a.account_id} value={a.account_id}>{a.code} {a.name}</option>)}</select></label><label>External transaction reference<input value={reference} maxLength={200} onChange={e=>setReference(e.target.value)}/></label><p>{rows.find(r=>r.id===source)?.category==='receivable'?'Records a collection against this receivable.':'Records a refund of held funds.'}</p></>}<label>Transaction period<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="">Choose period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive} (end excluded)</option>)}</select></label><label>Transaction date<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>Transaction amount (USD)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Transaction reason<input maxLength={500} value={reason} onChange={e=>setReason(e.target.value)}/></label></fieldset></>}<label><input type="checkbox" disabled={busy} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I reviewed the balance transaction details</label><button type="button" disabled={busy||!ready||!confirmed} onClick={()=>void run('save')}>{pending?'Retry balance transaction':'Record balance transaction'}</button>{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check balance transaction outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if balance transaction was not recorded</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel balance transaction request</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
